-- Curated questions for the Algebra, Geometry, Statistics, Probability,
-- Number Theory, and Measurement branches of the starter catalog.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en, quiz_fil=v.quiz_fil,
    explanation_en=v.explanation_en, explanation_fil=v.explanation_fil,
    options=v.options::jsonb
FROM (VALUES
 ('starter-math-algebra-variable', $$In 5 + x = 12, which symbol stands for the unknown quantity?$$, $$Sa 5 + x = 12, aling simbolo ang kumakatawan sa di-kilalang dami?$$, $$A variable is a symbol representing a number or quantity that can change.$$ , $$Simbolo ang variable na kumakatawan sa bilang o daming maaaring magbago.$$ , $$[{"en":"x","fil":"x","correct":true},{"en":"5","fil":"5","correct":false},{"en":"+","fil":"+","correct":false},{"en":"12 only","fil":"12 lamang","correct":false}]$$),
 ('starter-math-algebra-expression', $$Which expression represents “seven more than twice a number n”?$$, $$Aling expression ang kumakatawan sa “pitong dagdag sa dalawang beses ng bilang na n”?$$, $$Twice n is 2n, and seven more gives 2n + 7.$$ , $$2n ang dalawang beses ng n at 2n + 7 ito kapag dinagdagan ng pito.$$ , $$[{"en":"2n + 7","fil":"2n + 7","correct":true},{"en":"2(n + 7)","fil":"2(n + 7)","correct":false},{"en":"7n + 2","fil":"7n + 2","correct":false},{"en":"2n − 7","fil":"2n − 7","correct":false}]$$),
 ('starter-math-algebra-equation', $$A balance scale has equal total weight on both sides. Which mathematical statement models that equality?$$, $$Magkapantay ang kabuuang bigat sa magkabilang panig ng timbangan. Aling pahayag sa matematika ang nagmomodelo sa pagkakapantay na ito?$$, $$An equation states that two mathematical expressions have equal values.$$ , $$Ipinapahayag ng equation na magkapantay ang halaga ng dalawang mathematical expression.$$ , $$[{"en":"An equation","fil":"Equation","correct":true},{"en":"An inequality","fil":"Inequality","correct":false},{"en":"A variable alone","fil":"Variable lamang","correct":false},{"en":"A ratio without an equality statement","fil":"Ratio na walang pahayag ng pagkakapantay","correct":false}]$$),
 ('starter-math-algebra-inequality', $$A club allows at most 30 members. Which symbol expresses that the member count m cannot exceed 30?$$, $$Hanggang 30 miyembro lamang ang pinapayagan sa club. Aling simbolo ang nagsasaad na hindi lalampas sa 30 ang bilang na m?$$, $$“At most 30” means m is less than or equal to 30.$$ , $$Nangangahulugan ang “hanggang 30” na mas mababa o katumbas ng 30 ang m.$$ , $$[{"en":"m ≤ 30","fil":"m ≤ 30","correct":true},{"en":"m ≥ 30","fil":"m ≥ 30","correct":false},{"en":"m = 30 only","fil":"m = 30 lamang","correct":false},{"en":"m < 0","fil":"m < 0","correct":false}]$$),
 ('starter-math-algebra-coefficient', $$In the term −6y, what is the coefficient of y?$$, $$Sa term na −6y, ano ang coefficient ng y?$$, $$The coefficient is the number multiplying the variable, including its sign: −6.$$ , $$Ang coefficient ay bilang na minumultiply sa variable, kasama ang sign nito: −6.$$ , $$[{"en":"−6","fil":"−6","correct":true},{"en":"y","fil":"y","correct":false},{"en":"6y","fil":"6y","correct":false},{"en":"−1","fil":"−1","correct":false}]$$),
 ('starter-math-algebra-constant-term', $$In 4x² + 3x − 9, which term is constant?$$, $$Sa 4x² + 3x − 9, aling term ang constant?$$, $$A constant term has no variable, so −9 is the constant term.$$ , $$Walang variable ang constant term kaya −9 ang constant term.$$ , $$[{"en":"−9","fil":"−9","correct":true},{"en":"4x²","fil":"4x²","correct":false},{"en":"3x","fil":"3x","correct":false},{"en":"x²","fil":"x²","correct":false}]$$),
 ('starter-math-algebra-substitution', $$Evaluate 3x + 2 when x = 4.$$ , $$Kuwentahin ang 3x + 2 kapag x = 4.$$ , $$Substitute 4 for x: 3(4) + 2 = 14.$$ , $$Ipalit ang 4 sa x: 3(4) + 2 = 14.$$ , $$[{"en":"14","fil":"14","correct":true},{"en":"18","fil":"18","correct":false},{"en":"12","fil":"12","correct":false},{"en":"9","fil":"9","correct":false}]$$),
 ('starter-math-algebra-distributive', $$Expand 3(x + 4) using the distributive property.$$ , $$I-expand ang 3(x + 4) gamit ang distributive property.$$ , $$Multiply 3 by each term in the parentheses: 3x + 12.$$ , $$I-multiply ang 3 sa bawat term sa panaklong: 3x + 12.$$ , $$[{"en":"3x + 12","fil":"3x + 12","correct":true},{"en":"3x + 4","fil":"3x + 4","correct":false},{"en":"x + 12","fil":"x + 12","correct":false},{"en":"7x","fil":"7x","correct":false}]$$),
 ('starter-math-algebra-solution', $$For which value of x is the equation x + 5 = 12 true?$$ , $$Sa anong halaga ng x magiging totoo ang equation na x + 5 = 12?$$ , $$Subtracting 5 from both sides gives x = 7.$$ , $$Kapag binawasan ng 5 ang magkabilang panig, makukuha ang x = 7.$$ , $$[{"en":"7","fil":"7","correct":true},{"en":"5","fil":"5","correct":false},{"en":"12","fil":"12","correct":false},{"en":"17","fil":"17","correct":false}]$$),
 ('starter-math-algebra-equivalent', $$Which expression has the same value as 2(x + 3) for every x?$$ , $$Aling expression ang kapareho ng halaga ng 2(x + 3) para sa bawat x?$$ , $$Distributing 2 gives 2x + 6, so the expressions are equivalent.$$ , $$Kapag ipinamahagi ang 2, makukuha ang 2x + 6 kaya magkatumbas ang mga expression.$$ , $$[{"en":"2x + 6","fil":"2x + 6","correct":true},{"en":"2x + 3","fil":"2x + 3","correct":false},{"en":"x + 6","fil":"x + 6","correct":false},{"en":"2x − 6","fil":"2x − 6","correct":false}]$$),
 ('starter-math-geometry-point', $$A map marks a location with a dot but gives it no size. Which geometric idea does the dot represent?$$, $$Minarkahan sa mapa ng tuldok ang isang lokasyon ngunit wala itong sukat. Aling konsepto sa geometry ang kinakatawan nito?$$, $$A geometric point identifies a location and has no dimensions.$$ , $$Tumutukoy ng lokasyon ang geometric point at wala itong dimensiyon.$$ , $$[{"en":"Point","fil":"Point o punto","correct":true},{"en":"Line segment","fil":"Line segment","correct":false},{"en":"Plane","fil":"Plane o patag na ibabaw","correct":false},{"en":"Angle","fil":"Anggulo","correct":false}]$$),
 ('starter-math-geometry-line', $$A straight path continues forever in both directions. Which geometric object is it?$$, $$Walang katapusang nagpapatuloy sa magkabilang direksiyon ang tuwid na landas. Anong geometric object ito?$$, $$A line extends without end in both directions.$$ , $$Walang katapusang nagpapatuloy sa magkabilang direksiyon ang line.$$ , $$[{"en":"Line","fil":"Line o tuwid na linya","correct":true},{"en":"Ray","fil":"Ray","correct":false},{"en":"Line segment","fil":"Line segment","correct":false},{"en":"Polygon","fil":"Polygon","correct":false}]$$),
 ('starter-math-geometry-segment', $$A ruler shows the finite part of a straight path between two endpoints. What is this part called?$$, $$Ipinakikita ng ruler ang may hangganang bahagi ng tuwid na landas sa pagitan ng dalawang dulo. Ano ang tawag dito?$$, $$A line segment is part of a line with two endpoints.$$ , $$Bahagi ng line na may dalawang dulo ang line segment.$$ , $$[{"en":"Line segment","fil":"Line segment","correct":true},{"en":"A line extending forever","fil":"Line na walang hanggan","correct":false},{"en":"A plane","fil":"Plane","correct":false},{"en":"A circle arc with no endpoints","fil":"Arko ng bilog na walang dulo","correct":false}]$$),
 ('starter-math-geometry-parallel', $$Two rails lie in the same plane and never meet, even when extended. How are the lines related?$$, $$Magkapantay ang dalawang riles sa iisang plane at hindi nagtatagpo kahit pahabain. Ano ang ugnayan ng mga linya?$$, $$Parallel lines in the same plane do not intersect.$$ , $$Hindi nagtatagpo ang parallel lines na nasa iisang plane.$$ , $$[{"en":"Parallel","fil":"Parallel o magkaparallel","correct":true},{"en":"Perpendicular","fil":"Perpendicular","correct":false},{"en":"Intersecting at 90°","fil":"Nagtatagpo sa 90°","correct":false},{"en":"Curved","fil":"Kurbado","correct":false}]$$),
 ('starter-math-geometry-perpendicular', $$Two streets meet to form a right angle. What describes their relationship?$$, $$Nagtatagpo ang dalawang kalsada at bumubuo ng right angle. Ano ang naglalarawan sa ugnayan nila?$$, $$Perpendicular lines intersect to form right angles.$$ , $$Nagtatagpo ang perpendicular lines upang bumuo ng right angle.$$ , $$[{"en":"Perpendicular","fil":"Perpendicular","correct":true},{"en":"Parallel","fil":"Parallel","correct":false},{"en":"Skew in the same plane","fil":"Skew sa iisang plane","correct":false},{"en":"Curved and tangent","fil":"Kurbado at tangent","correct":false}]$$),
 ('starter-math-geometry-polygon', $$A closed, flat shape is made only from straight sides. What class of shape is it?$$, $$Binubuo lamang ng mga tuwid na gilid ang sarado at patag na hugis. Anong uri ng hugis ito?$$, $$A polygon is a closed flat shape made of straight line segments.$$ , $$Sarado at patag na hugis na binubuo ng mga tuwid na line segment ang polygon.$$ , $$[{"en":"Polygon","fil":"Polygon","correct":true},{"en":"Circle","fil":"Bilog","correct":false},{"en":"Open curve","fil":"Bukas na kurba","correct":false},{"en":"Solid sphere","fil":"Solidong sphere","correct":false}]$$),
 ('starter-math-geometry-quadrilateral', $$A tabletop has four straight sides and is a closed polygon. What is its most specific general name?$$, $$May apat na tuwid na gilid at saradong polygon ang ibabaw ng mesa. Ano ang pangkalahatang tawag dito?$$, $$A quadrilateral is a polygon with four sides.$$ , $$Polygon na may apat na gilid ang quadrilateral.$$ , $$[{"en":"Quadrilateral","fil":"Quadrilateral","correct":true},{"en":"Triangle","fil":"Tatsulok","correct":false},{"en":"Pentagon","fil":"Pentagon","correct":false},{"en":"Circle","fil":"Bilog","correct":false}]$$),
 ('starter-math-geometry-interior-sum', $$A quadrilateral has interior angles of 90°, 85°, and 100°. What is the fourth angle?$$, $$90°, 85°, at 100° ang mga interior angle ng quadrilateral. Ano ang ikaapat na anggulo?$$, $$A quadrilateral’s interior angles total 360°; the missing angle is 360 − 275 = 85°.$$ , $$360° ang kabuuan ng interior angle ng quadrilateral; 360 − 275 = 85° ang nawawalang anggulo.$$ , $$[{"en":"85°","fil":"85°","correct":true},{"en":"75°","fil":"75°","correct":false},{"en":"95°","fil":"95°","correct":false},{"en":"180°","fil":"180°","correct":false}]$$),
 ('starter-math-geometry-vertical-angles', $$Two straight lines cross. One angle is 48°. What is the angle directly opposite it?$$, $$Nagkrus ang dalawang tuwid na linya. 48° ang isang anggulo. Ano ang sukat ng anggulong kaharap nito?$$, $$Vertical angles are equal, so the opposite angle is 48°.$$ , $$Magkakapantay ang vertical angles kaya 48° din ang kaharap na anggulo.$$ , $$[{"en":"48°","fil":"48°","correct":true},{"en":"132°","fil":"132°","correct":false},{"en":"90°","fil":"90°","correct":false},{"en":"312°","fil":"312°","correct":false}]$$),
 ('starter-math-geometry-prism', $$A solid has two parallel, congruent triangular bases joined by rectangular side faces. What solid is it?$$, $$May dalawang magkapantay at magkaparehong triangular base ang solid na pinagdurugtong ng parihabang side face. Anong solid ito?$$, $$A prism has two parallel, congruent bases connected by side faces.$$ , $$May dalawang magkapantay at magkaparehong base ang prism na pinagdurugtong ng mga side face.$$ , $$[{"en":"Triangular prism","fil":"Triangular prism","correct":true},{"en":"Triangular pyramid","fil":"Triangular pyramid","correct":false},{"en":"Cone","fil":"Cone","correct":false},{"en":"Cylinder","fil":"Cylinder","correct":false}]$$),
 ('starter-math-statistics-population', $$A survey aims to describe every Grade 8 learner in a school. What group is the population?$$, $$Layunin ng survey na ilarawan ang lahat ng mag-aaral sa Grade 8 sa paaralan. Aling pangkat ang population?$$, $$The population is the entire group a statistical study aims to describe.$$ , $$Ang population ang buong pangkat na layong ilarawan ng pag-aaral sa estadistika.$$ , $$[{"en":"All Grade 8 learners in the school","fil":"Lahat ng mag-aaral sa Grade 8 sa paaralan","correct":true},{"en":"Only the learners who answered first","fil":"Mga unang sumagot lamang","correct":false},{"en":"One randomly chosen learner","fil":"Isang piniling mag-aaral lamang","correct":false},{"en":"The survey questions","fil":"Mga tanong sa survey","correct":false}]$$),
 ('starter-math-statistics-sample', $$Researchers ask 40 of a city’s 2,000 students about study habits. What are the 40 students?$$, $$Tinanong ng mga mananaliksik ang 40 sa 2,000 mag-aaral ng lungsod tungkol sa paraan ng pag-aaral. Ano ang 40 mag-aaral?$$, $$A sample is a subset selected from the population for study.$$ , $$Bahagi ng population na pinili para pag-aralan ang sample.$$ , $$[{"en":"A sample","fil":"Sample","correct":true},{"en":"The whole population","fil":"Buong population","correct":false},{"en":"A census of every student","fil":"Census ng lahat ng mag-aaral","correct":false},{"en":"A data category","fil":"Kategorya ng datos","correct":false}]$$),
 ('starter-math-statistics-random-sample', $$A school assigns every student a number and uses a random draw to select survey participants. Why is this a random sample?$$, $$Binigyan ng paaralan ng numero ang bawat mag-aaral at bumunot nang sapalaran para pumili ng sasagot sa survey. Bakit random sample ito?$$, $$Random sampling gives each population member a chance to be selected.$$ , $$Nagbibigay ng pagkakataong mapili ang bawat kasapi ng population sa random sampling.$$ , $$[{"en":"Each student has a chance to be selected","fil":"May pagkakataong mapili ang bawat mag-aaral","correct":true},{"en":"Only volunteers can be chosen","fil":"Mga boluntaryo lamang ang maaaring mapili","correct":false},{"en":"The researcher picks only friends","fil":"Mga kaibigan lamang ng mananaliksik ang pinipili","correct":false},{"en":"The first 40 students are always selected","fil":"Laging unang 40 mag-aaral ang pinipili","correct":false}]$$),
 ('starter-math-statistics-outlier', $$Most delivery times are 20–30 minutes, but one takes 150 minutes. What might 150 minutes be in the data set?$$, $$20–30 minuto ang karamihan ng oras ng delivery ngunit umabot ng 150 minuto ang isa. Ano ang maaaring tawag sa 150 minuto sa datos?$$, $$An outlier is a value unusually far from most values in a data set.$$ , $$Halagang malayong-malayo sa karamihan ng datos ang outlier.$$ , $$[{"en":"An outlier","fil":"Outlier","correct":true},{"en":"The mode in every data set","fil":"Mode sa bawat datos","correct":false},{"en":"The sample size","fil":"Laki ng sample","correct":false},{"en":"A category label","fil":"Pangalan ng kategorya","correct":false}]$$),
 ('starter-math-statistics-distribution', $$A teacher checks a graph showing how test scores cluster and spread. What is the graph describing?$$, $$Sinusuri ng guro ang graph na nagpapakita kung paano nagkakumpol at nagkakalat ang mga marka sa pagsusulit. Ano ang inilalarawan nito?$$, $$A data distribution shows how values are spread or grouped.$$ , $$Ipinakikita ng data distribution kung paano nagkakalat o nagkakagrupo ang mga halaga.$$ , $$[{"en":"The data distribution","fil":"Data distribution","correct":true},{"en":"The sample’s source only","fil":"Pinagmulan lamang ng sample","correct":false},{"en":"A geometric transformation","fil":"Geometric transformation","correct":false},{"en":"A single observation","fil":"Iisang obserbasyon","correct":false}]$$),
 ('starter-math-statistics-categorical', $$A survey records each learner’s favorite subject as Science, Math, or English. What kind of data are these?$$, $$Itinatala ng survey ang paboritong asignatura ng bawat mag-aaral bilang Science, Math, o English. Anong uri ng datos ito?$$, $$Categorical data describe groups or labels rather than numerical measurements.$$ , $$Naglalarawan ang categorical data ng mga pangkat o label sa halip na sukat na bilang.$$ , $$[{"en":"Categorical data","fil":"Categorical data","correct":true},{"en":"Numerical measurements","fil":"Numerical measurement","correct":false},{"en":"Continuous temperature data","fil":"Continuous na datos ng temperatura","correct":false},{"en":"A probability sample","fil":"Probability sample","correct":false}]$$),
 ('starter-math-statistics-numerical', $$A class records each learner’s height in centimeters. What kind of data are the heights?$$, $$Itinatala ng klase ang taas ng bawat mag-aaral sa sentimetro. Anong uri ng datos ang mga taas?$$, $$Numerical data are values representing counts or measurements.$$ , $$Mga halagang kumakatawan sa bilang o sukat ang numerical data.$$ , $$[{"en":"Numerical data","fil":"Numerical data","correct":true},{"en":"Categorical labels","fil":"Mga label ng kategorya","correct":false},{"en":"Names only","fil":"Mga pangalan lamang","correct":false},{"en":"Opinions without values","fil":"Opinyong walang halaga","correct":false}]$$),
 ('starter-math-statistics-line-plot', $$A teacher places one mark above a number line for every student who chose each shoe size. What display is being used?$$, $$Naglalagay ang guro ng marka sa ibabaw ng number line para sa bawat mag-aaral na pumili ng bawat sukat ng sapatos. Anong display ang ginagamit?$$, $$A line plot displays data values above a number line using marks or symbols.$$ , $$Ipinakikita ng line plot ang mga halaga ng datos sa ibabaw ng number line gamit ang mga marka o simbolo.$$ , $$[{"en":"Line plot","fil":"Line plot","correct":true},{"en":"Scatterplot of two variables","fil":"Scatterplot ng dalawang variable","correct":false},{"en":"Circle graph only","fil":"Circle graph lamang","correct":false},{"en":"Geometric proof","fil":"Geometric proof","correct":false}]$$),
 ('starter-math-probability-outcome', $$A die is rolled and shows 4. What is the 4 in this chance experiment?$$, $$Inihagis ang die at lumabas ang 4. Ano ang 4 sa eksperimento ng pagkakataon?$$, $$An outcome is one possible result of a chance process.$$ , $$Isang posibleng resulta ng prosesong may pagkakataon ang outcome.$$ , $$[{"en":"An outcome","fil":"Outcome o kalabasan","correct":true},{"en":"The full sample space","fil":"Buong sample space","correct":false},{"en":"An event containing every result","fil":"Event na naglalaman ng lahat ng resulta","correct":false},{"en":"A guaranteed result","fil":"Tiyak na resulta","correct":false}]$$),
 ('starter-math-probability-sample-space', $$A coin is flipped twice. Which set lists all possible ordered results?$$, $$Ihahagis nang dalawang beses ang barya. Aling set ang naglilista sa lahat ng posibleng nakaayos na resulta?$$, $$The sample space is the set of all possible outcomes; for two flips it is HH, HT, TH, TT.$$ , $$Ang sample space ang set ng lahat ng posibleng resulta; HH, HT, TH, TT ito para sa dalawang toss.$$ , $$[{"en":"{HH, HT, TH, TT}","fil":"{HH, HT, TH, TT}","correct":true},{"en":"{H, T}","fil":"{H, T}","correct":false},{"en":"{HH, TT}","fil":"{HH, TT}","correct":false},{"en":"{1, 2, 3, 4, 5, 6}","fil":"{1, 2, 3, 4, 5, 6}","correct":false}]$$),
 ('starter-math-probability-event', $$When rolling a die, getting an even number means getting 2, 4, or 6. What is this group of outcomes called?$$, $$Sa paghagis ng die, nangangahulugan ang pagkuha ng even number na lalabas ang 2, 4, o 6. Ano ang tawag sa pangkat na ito?$$, $$An event is one outcome or a group of outcomes in a probability experiment.$$ , $$Iisang resulta o pangkat ng mga resulta sa probability experiment ang event.$$ , $$[{"en":"An event","fil":"Event","correct":true},{"en":"A single sample point only","fil":"Iisang sample point lamang","correct":false},{"en":"The experiment itself","fil":"Ang eksperimento mismo","correct":false},{"en":"A measurement unit","fil":"Yunit ng pagsukat","correct":false}]$$),
 ('starter-math-probability-theoretical', $$A fair die has six equally likely faces. What is the theoretical probability of rolling a 2?$$, $$May anim na pantay na posibleng mukha ang patas na die. Ano ang theoretical probability na lumabas ang 2?$$, $$There is one favorable outcome among six equally likely outcomes, so the probability is 1/6.$$ , $$Isa ang paborableng resulta sa anim na pantay na resulta kaya 1/6 ang posibilidad.$$ , $$[{"en":"1/6","fil":"1/6","correct":true},{"en":"1/2","fil":"1/2","correct":false},{"en":"2/6","fil":"2/6","correct":false},{"en":"6/1","fil":"6/1","correct":false}]$$),
 ('starter-math-probability-experimental', $$A coin lands heads 18 times in 30 flips. What is the experimental probability of heads?$$, $$Ulo ang lumabas nang 18 beses sa 30 paghagis ng barya. Ano ang experimental probability ng ulo?$$, $$Experimental probability uses observed results: 18/30 = 3/5.$$ , $$Ginagamit ng experimental probability ang naobserbahang resulta: 18/30 = 3/5.$$ , $$[{"en":"3/5","fil":"3/5","correct":true},{"en":"1/2 exactly, regardless of results","fil":"Eksaktong 1/2 anuman ang resulta","correct":false},{"en":"18/12","fil":"18/12","correct":false},{"en":"30/18","fil":"30/18","correct":false}]$$),
 ('starter-math-probability-equally-likely', $$A fair coin has heads and tails, each with the same chance. How are these outcomes described?$$, $$May ulo at buntot ang patas na barya at magkapantay ang posibilidad ng mga ito. Paano inilalarawan ang mga outcome?$$, $$Equally likely outcomes have the same probability of occurring.$$ , $$Magkapantay ang posibilidad mangyari ng equally likely outcomes.$$ , $$[{"en":"Equally likely","fil":"Equally likely o pantay ang posibilidad","correct":true},{"en":"Mutually impossible","fil":"Imposibleng magsabay","correct":false},{"en":"Certain","fil":"Tiyak","correct":false},{"en":"Dependent in every case","fil":"Laging dependent","correct":false}]$$),
 ('starter-math-probability-complement', $$The chance of rain tomorrow is 0.3. What is the probability that it will not rain, using the complement?$$, $$0.3 ang posibilidad ng ulan bukas. Gamit ang complement, ano ang posibilidad na hindi uulan?$$, $$The complement is 1 − P(event), so 1 − 0.3 = 0.7.$$ , $$Ang complement ay 1 − P(event), kaya 1 − 0.3 = 0.7.$$ , $$[{"en":"0.7","fil":"0.7","correct":true},{"en":"0.3","fil":"0.3","correct":false},{"en":"1.3","fil":"1.3","correct":false},{"en":"0","fil":"0","correct":false}]$$),
 ('starter-math-probability-certain', $$Which value is a possible probability for an event that is certain to happen?$$, $$Aling halaga ang posibleng probability ng event na tiyak na mangyayari?$$, $$Probabilities range from 0 to 1 inclusive; a certain event has probability 1.$$ , $$Mula 0 hanggang 1 ang probability; 1 ang probability ng tiyak na event.$$ , $$[{"en":"1","fil":"1","correct":true},{"en":"−0.2","fil":"−0.2","correct":false},{"en":"1.4","fil":"1.4","correct":false},{"en":"−1","fil":"−1","correct":false}]$$),
 ('starter-math-numbertheory-factor', $$The number 4 divides 20 with no remainder. What is 4 in relation to 20?$$, $$Nahahati ng 4 ang 20 nang walang remainder. Ano ang ugnayan ng 4 sa 20?$$, $$A factor divides a whole number evenly with no remainder.$$ , $$Nahahati nang walang remainder ang whole number sa factor nito.$$ , $$[{"en":"A factor of 20","fil":"Factor ng 20","correct":true},{"en":"A prime factor larger than 20","fil":"Prime factor na mas malaki sa 20","correct":false},{"en":"A remainder of 20","fil":"Remainder na 20","correct":false},{"en":"A multiple smaller than 4","fil":"Multiple na mas maliit sa 4","correct":false}]$$),
 ('starter-math-numbertheory-multiple', $$The sequence 6, 12, 18, 24 is formed by multiplying 6 by whole numbers. What are these values?$$, $$Nabuo ang 6, 12, 18, 24 sa pag-multiply ng 6 sa mga whole number. Ano ang tawag sa mga halagang ito?$$, $$A multiple is the product of a number and an integer.$$ , $$Produkto ng isang bilang at integer ang multiple.$$ , $$[{"en":"Multiples of 6","fil":"Mga multiple ng 6","correct":true},{"en":"Factors of 6","fil":"Mga factor ng 6","correct":false},{"en":"Prime numbers only","fil":"Prime number lamang","correct":false},{"en":"Remainders when dividing by 6","fil":"Remainder sa paghahati sa 6","correct":false}]$$),
 ('starter-math-numbertheory-gcf', $$What is the greatest common factor of 18 and 24?$$, $$Ano ang greatest common factor ng 18 at 24?$$, $$The shared factors include 1, 2, 3, and 6; the greatest is 6.$$ , $$Kabilang sa mga magkaparehong factor ang 1, 2, 3, at 6; 6 ang pinakamalaki.$$ , $$[{"en":"6","fil":"6","correct":true},{"en":"3","fil":"3","correct":false},{"en":"12","fil":"12","correct":false},{"en":"72","fil":"72","correct":false}]$$),
 ('starter-math-numbertheory-lcm', $$Two alarms ring every 6 and 8 minutes. After how many minutes will they ring together again?$$, $$Tuwing 6 at 8 minuto tumutunog ang dalawang alarm. Pagkalipas ng ilang minuto uli silang sabay tutunog?$$, $$The least common multiple of 6 and 8 is 24, so they ring together after 24 minutes.$$ , $$24 ang least common multiple ng 6 at 8 kaya sabay silang tutunog makalipas ang 24 minuto.$$ , $$[{"en":"24 minutes","fil":"24 minuto","correct":true},{"en":"14 minutes","fil":"14 minuto","correct":false},{"en":"48 minutes","fil":"48 minuto","correct":false},{"en":"6 minutes","fil":"6 minuto","correct":false}]$$),
 ('starter-math-numbertheory-divisible', $$A number is divisible by 5 when its division by 5 leaves what?$$, $$Nahahati ang bilang sa 5 kapag ano ang natitira sa paghahati nito sa 5?$$, $$Divisibility means division leaves no remainder.$$ , $$Nangangahulugan ang divisibility na walang remainder sa paghahati.$$ , $$[{"en":"No remainder","fil":"Walang remainder","correct":true},{"en":"A remainder of 5","fil":"Remainder na 5","correct":false},{"en":"A quotient of zero","fil":"Quotient na zero","correct":false},{"en":"A negative divisor","fil":"Negative na divisor","correct":false}]$$),
 ('starter-math-numbertheory-square', $$A square garden has side length 7 m. Which number is its area, a perfect square?$$, $$May side na 7 m ang parisukat na hardin. Aling bilang ang area nito na perfect square?$$, $$A perfect square is an integer multiplied by itself; 7 × 7 = 49.$$ , $$Ang perfect square ay integer na minultiply sa sarili nito; 7 × 7 = 49.$$ , $$[{"en":"49","fil":"49","correct":true},{"en":"14","fil":"14","correct":false},{"en":"21","fil":"21","correct":false},{"en":"7","fil":"7","correct":false}]$$),
 ('starter-math-numbertheory-absolute', $$How far is −8 from zero on a number line?$$, $$Gaano kalayo ang −8 mula sa zero sa number line?$$, $$Absolute value is distance from zero, so |−8| = 8.$$ , $$Distansiya mula sa zero ang absolute value kaya |−8| = 8.$$ , $$[{"en":"8","fil":"8","correct":true},{"en":"−8","fil":"−8","correct":false},{"en":"0","fil":"0","correct":false},{"en":"16","fil":"16","correct":false}]$$),
 ('starter-math-numbertheory-opposite', $$What is the opposite of 9 on a number line?$$, $$Ano ang opposite ng 9 sa number line?$$, $$Opposite numbers have the same distance from zero on opposite sides, so the opposite of 9 is −9.$$ , $$Magkapantay ang layo sa zero ng opposite numbers ngunit nasa magkabilang panig, kaya −9 ang opposite ng 9.$$ , $$[{"en":"−9","fil":"−9","correct":true},{"en":"9","fil":"9","correct":false},{"en":"0","fil":"0","correct":false},{"en":"1/9","fil":"1/9","correct":false}]$$),
 ('starter-math-measurement-radius', $$A circle’s center is connected to a point on its edge. What is this segment called?$$, $$Ikinokonekta ang gitna ng bilog sa isang punto sa gilid nito. Ano ang tawag sa segment na ito?$$, $$A radius runs from the center of a circle to its edge.$$ , $$Mula sa gitna ng bilog hanggang sa gilid nito ang radius.$$ , $$[{"en":"Radius","fil":"Radius","correct":true},{"en":"Diameter","fil":"Diameter","correct":false},{"en":"Circumference","fil":"Circumference","correct":false},{"en":"Chord through the center’s exterior","fil":"Chord sa labas ng gitna","correct":false}]$$),
 ('starter-math-measurement-diameter', $$A circle has a radius of 6 cm. What is its diameter?$$, $$6 cm ang radius ng bilog. Ano ang diameter nito?$$, $$A diameter is two radii, so 2 × 6 = 12 cm.$$ , $$Dalawang radius ang diameter kaya 2 × 6 = 12 cm.$$ , $$[{"en":"12 cm","fil":"12 cm","correct":true},{"en":"6 cm","fil":"6 cm","correct":false},{"en":"18 cm","fil":"18 cm","correct":false},{"en":"36 cm²","fil":"36 cm²","correct":false}]$$),
 ('starter-math-measurement-circle-area', $$A circular plate has radius r. Which formula gives the area inside its edge?$$, $$May radius na r ang pabilog na plato. Aling formula ang nagbibigay ng lawak sa loob ng gilid nito?$$, $$The area of a circle is π times the radius squared: A = πr².$$ , $$π na minultiply sa radius squared ang area ng bilog: A = πr².$$ , $$[{"en":"A = πr²","fil":"A = πr²","correct":true},{"en":"A = 2πr","fil":"A = 2πr","correct":false},{"en":"A = πd","fil":"A = πd","correct":false},{"en":"A = r + r","fil":"A = r + r","correct":false}]$$),
 ('starter-math-measurement-triangle-area', $$A triangle has base 10 cm and height 6 cm. What is its area?$$, $$10 cm ang base at 6 cm ang height ng tatsulok. Ano ang area nito?$$, $$Triangle area is one half times base times height: ½ × 10 × 6 = 30 cm².$$ , $$Kalahati ng base na minultiply sa height ang area ng tatsulok: ½ × 10 × 6 = 30 cm².$$ , $$[{"en":"30 cm²","fil":"30 cm²","correct":true},{"en":"60 cm²","fil":"60 cm²","correct":false},{"en":"16 cm²","fil":"16 cm²","correct":false},{"en":"30 cm","fil":"30 cm","correct":false}]$$),
 ('starter-math-measurement-perimeter', $$A rectangular pen has side lengths 5 m and 3 m. What is its perimeter?$$, $$5 m at 3 m ang magkabilang sukat ng parihabang kulungan. Ano ang perimeter nito?$$, $$Perimeter adds all sides: 5 + 3 + 5 + 3 = 16 m.$$ , $$Pinagsasama ng perimeter ang haba ng lahat ng gilid: 5 + 3 + 5 + 3 = 16 m.$$ , $$[{"en":"16 m","fil":"16 m","correct":true},{"en":"15 m²","fil":"15 m²","correct":false},{"en":"8 m","fil":"8 m","correct":false},{"en":"30 m","fil":"30 m","correct":false}]$$),
 ('starter-math-measurement-volume', $$A box occupies 24 cubic centimeters of space. What quantity does 24 cm³ measure?$$, $$Sumasakop ang kahon ng 24 cubic centimeter na espasyo. Anong dami ang sinusukat ng 24 cm³?$$, $$Volume measures the three-dimensional space an object occupies.$$ , $$Sinusukat ng volume ang three-dimensional na espasyong sinasakop ng bagay.$$ , $$[{"en":"Volume","fil":"Volume","correct":true},{"en":"Perimeter","fil":"Perimeter","correct":false},{"en":"Area","fil":"Area o lawak","correct":false},{"en":"Mass","fil":"Masa","correct":false}]$$),
 ('starter-math-measurement-surface-area', $$A student paints every outside face of a cube. Which measurement gives the total area to paint?$$, $$Pipinturahan ng mag-aaral ang lahat ng panlabas na mukha ng cube. Aling sukat ang kabuuang area na pipinturahan?$$, $$Surface area is the sum of the areas of all outer faces.$$ , $$Kabuuan ng area ng lahat ng panlabas na mukha ang surface area.$$ , $$[{"en":"Surface area","fil":"Surface area","correct":true},{"en":"Volume","fil":"Volume","correct":false},{"en":"Perimeter of one face","fil":"Perimeter ng isang mukha","correct":false},{"en":"Mass","fil":"Masa","correct":false}]$$),
 ('starter-math-measurement-unit', $$A notebook is 25 long. What must be added to this measurement to make it meaningful?$$, $$25 ang haba ng notebook. Ano ang kailangang idagdag upang maging malinaw ang sukat?$$, $$A measurement needs both a number and a unit, such as 25 centimeters.$$ , $$Kailangan ng measurement ang bilang at yunit, gaya ng 25 sentimetro.$$ , $$[{"en":"A unit, such as centimeters","fil":"Yunit, gaya ng sentimetro","correct":true},{"en":"A second number only","fil":"Ikalawang bilang lamang","correct":false},{"en":"A color name","fil":"Pangalan ng kulay","correct":false},{"en":"A larger numeral without a unit","fil":"Mas malaking bilang na walang yunit","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,explanation_en,explanation_fil,options)
WHERE c.content_key=v.content_key;
